29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.rest.assignment.CustomerCodeGenerator;
39	import org.springframework.samples.petclinic.rest.assignment.HouseholdRegistrar;
40	import org.springframework.samples.petclinic.rest.audit.OwnerAuditLogger;
41	import org.springframework.samples.petclinic.rest.error.DuplicateTelephoneException;
42	import org.springframework.samples.petclinic.rest.signup.BulkSignupWarningEvaluator;
43	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
44	import org.springframework.samples.petclinic.rest.validation.CityOwnerLimitValidator;
45	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitValidator;
46	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.HouseholdDuplicateValidator;
48	import org.springframework.samples.petclinic.rest.validation.OwnerRequestValidator;
49	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    private final OwnerRequestValidator ownerRequestValidator;
77	
78	    private final HouseholdDuplicateValidator householdDuplicateValidator;
79	
80	    private final CityOwnerLimitValidator cityOwnerLimitValidator;
81	
82	    private final DailyOwnerLimitValidator dailyOwnerLimitValidator;
83	
84	    private final TelephoneNormalizer telephoneNormalizer;
85	
86	    private final EmailNormalizer emailNormalizer;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    private final CustomerCodeGenerator customerCodeGenerator;
91	
92	    private final HouseholdRegistrar householdRegistrar;
93	
94	    private final OwnerAuditLogger ownerAuditLogger;
95	
96	    private final BulkSignupWarningEvaluator bulkSignupWarningEvaluator;
97	
98	    public OwnerRestControllerV1(ClinicService clinicService,
99	                                 OwnerMapper ownerMapper,
100	                                 PetMapper petMapper,
101	                                 VisitMapper visitMapper,
102	                                 OwnerRequestValidator ownerRequestValidator,
103	                                 HouseholdDuplicateValidator householdDuplicateValidator,
104	                                 CityOwnerLimitValidator cityOwnerLimitValidator,
105	                                 DailyOwnerLimitValidator dailyOwnerLimitValidator,
106	                                 TelephoneNormalizer telephoneNormalizer,
107	                                 EmailNormalizer emailNormalizer,
108	                                 AddressNormalizer addressNormalizer,
109	                                 CustomerCodeGenerator customerCodeGenerator,
110	                                 HouseholdRegistrar householdRegistrar,
111	                                 OwnerAuditLogger ownerAuditLogger,
112	                                 BulkSignupWarningEvaluator bulkSignupWarningEvaluator) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.ownerRequestValidator = ownerRequestValidator;
118	        this.householdDuplicateValidator = householdDuplicateValidator;
119	        this.cityOwnerLimitValidator = cityOwnerLimitValidator;
120	        this.dailyOwnerLimitValidator = dailyOwnerLimitValidator;
121	        this.telephoneNormalizer = telephoneNormalizer;
122	        this.emailNormalizer = emailNormalizer;
123	        this.addressNormalizer = addressNormalizer;
124	        this.customerCodeGenerator = customerCodeGenerator;
125	        this.householdRegistrar = householdRegistrar;
126	        this.ownerAuditLogger = ownerAuditLogger;
127	        this.bulkSignupWarningEvaluator = bulkSignupWarningEvaluator;
128	    }
129	
130	    /**
131	     * Map an owner to its DTO and stamp the current bulk-signup warning onto it, so every
132	     * single-owner response reflects whether more than 80 owners have been created today.
133	     */
134	    private OwnerDto toOwnerDto(Owner owner) {
135	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
136	        ownerDto.setBulkSignupWarning(this.bulkSignupWarningEvaluator.isBulkSignupInEffect());
137	        return ownerDto;
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
143	        Collection<Owner> owners;
144	        if (lastName != null) {
145	            owners = this.clinicService.findOwnerByLastName(lastName);
146	        } else {
147	            owners = this.clinicService.findAllOwners();
148	        }
149	        if (owners.isEmpty()) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
168	        ownerFieldsDto.setAddress(this.addressNormalizer.normalize(ownerFieldsDto.getAddress()));
169	        this.ownerRequestValidator.validate(ownerFieldsDto);
170	        this.householdDuplicateValidator.validate(ownerFieldsDto);
171	        this.cityOwnerLimitValidator.validate(ownerFieldsDto);
172	        this.dailyOwnerLimitValidator.validate(ownerFieldsDto.getRegistrationDate());
173	        String telephone = this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
174	        ownerFieldsDto.setTelephone(telephone);
175	        ownerFieldsDto.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
176	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
177	            throw new DuplicateTelephoneException(telephone);
178	        }
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        owner.setCustomerCode(
182	            this.customerCodeGenerator.generate(owner.getCity(), owner.getLastName(),
183	                this.clinicService.countOwnersInCity(owner.getCity())));
184	        owner.setNamesakeCount(
185	            (int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
186	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
187	            owner.setHouseholdSize(this.householdRegistrar.register(owner));
188	        }
189	        this.clinicService.saveOwner(owner);
190	        this.ownerAuditLogger.created(owner);
191	        OwnerDto ownerDto = toOwnerDto(owner);
192	        headers.setLocation(UriComponentsBuilder.newInstance()
193	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
194	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
200	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
201	        if (currentOwner == null) {
202	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
203	        }
204	        currentOwner.setAddress(ownerFieldsDto.getAddress());
205	        currentOwner.setCity(ownerFieldsDto.getCity());
206	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
207	        currentOwner.setLastName(ownerFieldsDto.getLastName());
208	        currentOwner.setTelephone(this.telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
209	        currentOwner.setEmail(this.emailNormalizer.normalize(ownerFieldsDto.getEmail()));
210	        this.clinicService.saveOwner(currentOwner);
211	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Transactional
216	    @Override
217	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
218	        Owner owner = this.clinicService.findOwnerById(ownerId);
219	        if (owner == null) {
220	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
221	        }
222	        this.clinicService.deleteOwner(owner);
223	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner == null) {
231	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	        }
233	        HttpHeaders headers = new HttpHeaders();
234	        Pet pet = petMapper.toPet(petFieldsDto);
235	        owner.setId(ownerId);
236	        pet.setOwner(owner);
237	        pet.getType().setName(null);
238	        this.clinicService.savePet(pet);
239	        PetDto petDto = petMapper.toPetDto(pet);
240	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
241	            .buildAndExpand(pet.getId()).toUri());
242	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
248	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
249	        if (currentOwner != null) {
250	            Pet currentPet = this.clinicService.findPetById(petId);
251	            if (currentPet != null) {
252	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
253	                currentPet.setName(petFieldsDto.getName());
254	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
255	                this.clinicService.savePet(currentPet);
256	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
257	            }
258	        }
259	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	    }
261	
262	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
263	    @Override
264	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
265	        HttpHeaders headers = new HttpHeaders();
266	        Visit visit = visitMapper.toVisit(visitFieldsDto);
267	        Pet pet = new Pet();
268	        pet.setId(petId);
269	        visit.setPet(pet);
270	        this.clinicService.saveVisit(visit);
271	        VisitDto visitDto = visitMapper.toVisitDto(visit);
272	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
273	            .buildAndExpand(visit.getId()).toUri());
274	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
275	    }
276	
277	
278	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
279	    @Override
280	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
281	        Owner owner = this.clinicService.findOwnerById(ownerId);
282	        if (owner != null) {
283	            Pet pet = owner.getPet(petId);
284	            if (pet != null) {
285	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
286	            }
287	        }
288	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
289	    }
290	}
