package org.springframework.samples.petclinic.rest.error;

/**
 * Thrown when an owner is created with a normalized telephone number that is already used by
 * another owner. Carries the conflicting normalized value so the REST layer can report what was
 * rejected.
 */
public class DuplicateTelephoneException extends RuntimeException {

    private final String telephone;

    public DuplicateTelephoneException(String telephone) {
