17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.rest.error.CityOwnerLimitExceededException;
34	import org.springframework.samples.petclinic.rest.error.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.rest.error.DuplicateHouseholdException;
36	import org.springframework.samples.petclinic.rest.error.DuplicateTelephoneException;
37	import org.springframework.samples.petclinic.rest.error.InvalidEmailException;
38	import org.springframework.samples.petclinic.rest.error.InvalidTelephoneException;
39	import org.springframework.samples.petclinic.rest.error.RequiredFieldsMissingException;
40	import org.springframework.security.access.AccessDeniedException;
41	import org.springframework.validation.BindingResult;
42	import org.springframework.web.bind.MethodArgumentNotValidException;
43	import org.springframework.web.bind.annotation.ControllerAdvice;
44	import org.springframework.web.bind.annotation.ExceptionHandler;
45	import org.springframework.web.bind.annotation.ResponseBody;
46	
47	/**
48	 * Global Exception handler for REST controllers.
49	 * <p>
50	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
51	 *
52	 * @author Vitaliy Fedoriv
53	 * @author Alexander Dudkin
54	 */
55	@ControllerAdvice
56	public class ExceptionControllerAdvice {
57	
58	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
59	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
60	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
61	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
62	
63	    /**
64	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
65	     * class.
66	     *
67	     * @param e     Object referring to the thrown exception.
68	     * @param status HTTP response status.
69	     * @param url URL request.
70	     */
71	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
72	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
73	        problemDetail.setType(URI.create(url.toString()));
74	        problemDetail.setTitle(e.getClass().getSimpleName());
75	        problemDetail.setDetail(detail);
76	        problemDetail.setProperty("timestamp", Instant.now());
77	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
78	        return problemDetail;
79	    }
80	
81	    /**
82	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
83	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
84	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
85	     * would catch it and report an authorization failure as a 500.
86	     *
87	     * @param e The {@link AccessDeniedException} to propagate
88	     * @throws AccessDeniedException always
89	     */
90	    @ExceptionHandler(AccessDeniedException.class)
91	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
92	        throw e;
93	    }
94	
95	    /**
96	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
97	     *
98	     * @param e The {@link Exception} to be handled
99	     * @param request {@link HttpServletRequest} object referring to the current request.
100	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
101	     */
102	    @ExceptionHandler(Exception.class)
103	    @ResponseBody
104	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
105	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
106	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
107	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
108	        return ResponseEntity.status(status).body(detail);
109	    }
110	
111	    /**
112	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
113	     * method returns a 404 Not Found status if an entity does not exist.
114	     *
115	     * @param e The {@link DataIntegrityViolationException} to be handled
116	     * @param request {@link HttpServletRequest} object referring to the current request.
117	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
118	     */
119	    @ExceptionHandler(DataIntegrityViolationException.class)
120	    @ResponseBody
121	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
122	        logger.warn("Data integrity violation at {} {}: {}",
123	            request.getMethod(),
124	            request.getRequestURI(),
125	            e.getMessage());
126	        logger.debug("Data integrity violation stacktrace", e);
127	        HttpStatus status = HttpStatus.NOT_FOUND;
128	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
129	        return ResponseEntity.status(status).body(detail);
130	    }
131	
132	    /**
133	     * Handles exception thrown by Bean Validation on controller methods parameters
134	     *
135	     * @param e The {@link MethodArgumentNotValidException} to be handled
136	     * @param request {@link HttpServletRequest} object referring to the current request.
137	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
138	     */
139	    @ExceptionHandler(MethodArgumentNotValidException.class)
140	    @ResponseBody
141	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
142	        HttpStatus status = HttpStatus.BAD_REQUEST;
143	        BindingErrorsResponse errors = new BindingErrorsResponse();
144	        BindingResult bindingResult = e.getBindingResult();
145	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
146	        if (bindingResult.hasErrors()) {
147	            errors.addAllErrors(bindingResult);
148	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
149	                .map(fieldError -> fieldError.getField())
150	                .distinct()
151	                .toList();
152	            detail.setProperty("errors", invalidFields);
153	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
154	                .map(fieldError -> {
155	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
156	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
157	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
158	                        fieldError.getField(),
159	                        defaultMessage,
160	                        rejectedValue);
161	                    return new ValidationMessageDto(message)
162	                        .putAdditionalProperty("field", fieldError.getField())
163	                        .putAdditionalProperty("rejectedValue", rejectedValue)
164	                        .putAdditionalProperty("defaultMessage", defaultMessage);
165	                })
166	                .toList();
167	            logger.debug("Validation error at {} {}: {}",
168	                request.getMethod(),
169	                request.getRequestURI(),
170	                bindingResult.getFieldErrors());
171	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
172	            return ResponseEntity.status(status).body(detail);
173	        }
174	        return ResponseEntity.status(status).body(detail);
175	    }
176	
177	    /**
178	     * Handles {@link RequiredFieldsMissingException} thrown when a request omits or leaves blank a
179	     * mandatory field. Returns a 400 Bad Request whose {@code errors} array names each missing field.
180	     *
181	     * @param e The {@link RequiredFieldsMissingException} to be handled
182	     * @param request {@link HttpServletRequest} object referring to the current request.
183	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
184	     */
185	    @ExceptionHandler(RequiredFieldsMissingException.class)
186	    @ResponseBody
187	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
188	        logger.debug("Missing required fields at {} {}: {}",
189	            request.getMethod(),
190	            request.getRequestURI(),
191	            e.getMissingFields());
192	        HttpStatus status = HttpStatus.BAD_REQUEST;
193	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
194	        detail.setProperty("errors", e.getMissingFields());
195	        return ResponseEntity.status(status).body(detail);
196	    }
197	
198	    /**
199	     * Handles {@link InvalidTelephoneException} thrown when a submitted telephone number does not
200	     * contain exactly ten digits once every non-digit character has been stripped. Returns a
201	     * 400 Bad Request naming the offending field.
202	     *
203	     * @param e The {@link InvalidTelephoneException} to be handled
204	     * @param request {@link HttpServletRequest} object referring to the current request.
205	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
206	     */
207	    @ExceptionHandler(InvalidTelephoneException.class)
208	    @ResponseBody
209	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
210	        logger.debug("Invalid telephone at {} {}: {}",
211	            request.getMethod(),
212	            request.getRequestURI(),
213	            e.getRejectedValue());
214	        HttpStatus status = HttpStatus.BAD_REQUEST;
215	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
216	        detail.setProperty("errors", List.of("telephone"));
217	        return ResponseEntity.status(status).body(detail);
218	    }
219	
220	    /**
221	     * Handles {@link InvalidEmailException} thrown when a submitted email address is present but not
222	     * a syntactically valid address. Returns a 400 Bad Request naming the offending field.
223	     *
224	     * @param e The {@link InvalidEmailException} to be handled
225	     * @param request {@link HttpServletRequest} object referring to the current request.
226	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
227	     */
228	    @ExceptionHandler(InvalidEmailException.class)
229	    @ResponseBody
230	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
231	        logger.debug("Invalid email at {} {}: {}",
232	            request.getMethod(),
233	            request.getRequestURI(),
234	            e.getRejectedValue());
235	        HttpStatus status = HttpStatus.BAD_REQUEST;
236	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
237	        detail.setProperty("errors", List.of("email"));
238	        return ResponseEntity.status(status).body(detail);
239	    }
240	
241	    /**
242	     * Handles {@link DuplicateTelephoneException} thrown when an owner is created with a normalized
243	     * telephone number that is already used by another owner. Returns a 409 Conflict naming the
244	     * offending field.
245	     *
246	     * @param e The {@link DuplicateTelephoneException} to be handled
247	     * @param request {@link HttpServletRequest} object referring to the current request.
248	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
249	     */
250	    @ExceptionHandler(DuplicateTelephoneException.class)
251	    @ResponseBody
252	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
253	        logger.debug("Duplicate telephone at {} {}: {}",
254	            request.getMethod(),
255	            request.getRequestURI(),
256	            e.getTelephone());
257	        HttpStatus status = HttpStatus.CONFLICT;
258	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
259	        detail.setProperty("errors", List.of("telephone"));
260	        return ResponseEntity.status(status).body(detail);
261	    }
262	
263	    /**
264	     * Handles {@link DuplicateHouseholdException} thrown when an owner is created whose last name and
265	     * address match those of an existing owner and the request did not opt in to a shared household.
266	     * Returns a 409 Conflict naming the offending fields.
267	     *
268	     * @param e The {@link DuplicateHouseholdException} to be handled
269	     * @param request {@link HttpServletRequest} object referring to the current request.
270	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
271	     */
272	    @ExceptionHandler(DuplicateHouseholdException.class)
273	    @ResponseBody
274	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
275	        logger.debug("Duplicate household at {} {}: {} / {}",
276	            request.getMethod(),
277	            request.getRequestURI(),
278	            e.getLastName(),
279	            e.getAddress());
280	        HttpStatus status = HttpStatus.CONFLICT;
281	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
282	        detail.setProperty("errors", List.of("lastName", "address"));
283	        return ResponseEntity.status(status).body(detail);
284	    }
285	
286	    /**
287	     * Handles {@link CityOwnerLimitExceededException} thrown when an owner is created in a city that
288	     * already contains the maximum permitted number of owners. Returns a 409 Conflict naming the
289	     * offending field.
290	     *
291	     * @param e The {@link CityOwnerLimitExceededException} to be handled
292	     * @param request {@link HttpServletRequest} object referring to the current request.
293	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
294	     */
295	    @ExceptionHandler(CityOwnerLimitExceededException.class)
296	    @ResponseBody
297	    public ResponseEntity<ProblemDetail> handleCityOwnerLimitExceededException(CityOwnerLimitExceededException e, HttpServletRequest request) {
298	        logger.debug("City owner limit exceeded at {} {}: {}",
299	            request.getMethod(),
300	            request.getRequestURI(),
301	            e.getCity());
302	        HttpStatus status = HttpStatus.CONFLICT;
303	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
304	        detail.setProperty("errors", List.of("city"));
305	        return ResponseEntity.status(status).body(detail);
306	    }
307	
308	    /**
309	     * Handles {@link DailyOwnerLimitExceededException} thrown when an owner is created on a day that
310	     * has already reached the maximum permitted number of owner registrations. Returns a 429 Too
311	     * Many Requests.
312	     *
313	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
314	     * @param request {@link HttpServletRequest} object referring to the current request.
315	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
316	     */
317	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
318	    @ResponseBody
319	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
320	        logger.debug("Daily owner limit exceeded at {} {}: {}",
321	            request.getMethod(),
322	            request.getRequestURI(),
323	            e.getRegistrationDate());
324	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
325	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
326	        return ResponseEntity.status(status).body(detail);
327	    }
328	
329	}
